                "• მარსელელმა მოხელემ, პიერ დ’არნუმ, 1714 წელს ლუი XIV-ისთვის მემორანდუმი შეადგინა. მისი აზრით, საბას წინადადებები ერთ დიდ პროექტად უნდა გაერთიანებულიყო: გავრცელდებოდა კათოლიკობა, დაეხმარებოდნენ ქართველ მთავრებს და გაძლიერდებოდა საფრანგეთის ვაჭრობა — ჰოლანდიელების, პორტუგალიელებისა და ინგლისელების საწინააღმდეგოდ.\n• საბა გვთავაზობდა, რომ გილანისა და შემახიის აბრეშუმი საქართველოს გავლით გასულიყო. სომეხი ვაჭრები მას თურქეთის გავლით ქარავნებით სმირნამდე ეზიდებოდნენ — საქართველოზე გზა სამი მეოთხედით მოკლე იქნებოდა.\n• რატომ არ დადიოდნენ ვაჭრები ამ გზით? საბას პასუხით, ისინი ქართველების მფარველობის ქვეშ არ იყვნენ, ქვეყანას არასანდოდ თვლიდნენ და აქ თურქეთის მსგავსი ქარვასლები არ იყო. თუ ვახტანგი ტახტს დაიბრუნებდა, ამ ვაჭრობას თავად წამოიწყებდა და აბრეშუმს კონსტანტინოპოლში ჩაიტანდა.\n• საფრანგეთს საქართველოს ბაზრებზე ცვილი, მატყლი, ტყვია და წითელი საღებავის მომცემი ენდროს ფესვიც აინტერესებდა, თავად კი აქ მაუდის გაყიდვა შეეძლო.",
