                "• 1697 წელს რუსეთიდან ევროპაში 250-კაციანი „დიდი ელჩობა“ გაემგზავრა. მიზანი იყო თურქების წინააღმდეგ მოკავშირეების პოვნა, იარაღის შესყიდვა და უცხოელი სპეციალისტების მოწვევა.\n• ელჩობაში თავად მეფეც მონაწილეობდა — შენიღბულად, პეტრე მიხაილოვის სახელით. ეს იყო პირველი შემთხვევა რუსეთის ისტორიაში, როცა მეფე საზღვარგარეთ იმოგზაურა.\n• ინგლისში პეტრემ დაათვალიერა გრინვიჩის ობსერვატორია, ზარაფხანა, სამეფო საზოგადოება და ოქსფორდის უნივერსიტეტი, თავად შეისწავლა საათების დამზადება, დიდი დრო დაუთმო გემთმშენებლობას. ელჩობამ გერმანია, ჰოლანდია და ავსტრიაც მოიარა.\n• წელიწად-ნახევრის შემდეგ ელჩობა დაბრუნდა. მოკავშირეები ვერ იპოვეს, მაგრამ იარაღი შეისყიდეს და უცხოელი სპეციალისტები მოიწვიეს.",
