              title: "ჩრდილოეთის ომი და ახალი დედაქალაქი",
              paragraphs: [
                "• 1700–1721 წლებში რუსეთი შვედეთს ებრძოდა — ეს ომი ჩრდილოეთის ომის სახელითაა ცნობილი.\n• ჯერ კიდევ ომის დროს, 1703 წელს, შვედებისთვის წართმეულ მიწაზე პეტრემ ახალი ქალაქის — სანქტ-პეტერბურგის, მომავალი დედაქალაქის — მშენებლობა დაიწყო. ქალაქს უცხოელი არქიტექტორები აშენებდნენ.\n• სანქტ-პეტერბურგში ბევრი საზოგადოებრივი შენობა იყო — თეატრი, მუზეუმი, — რაც მანამდე რუსეთის ყოფისთვის უცხო იყო.\n• ჩრდილოეთის ომში გამარჯვების აღსანიშნავად რუსეთი იმპერიად გამოცხადდა, პეტრე I-ს კი „მთელი რუსეთის იმპერატორი“ ეწოდა.",
              ],
