                "• ხრესილის შემდეგ სოლომონმა რეფორმები გააძლიერა. უმნიშვნელოვანესი იყო ტყვეთა სყიდვის აკრძალვა — ამისთვის მეფემ დასავლეთ საქართველოს მთელი თავადაზნაურობა შეკრიბა.\n• კრებამ დაადგინა: ვინც ტყვეებით ვაჭრობას გააგრძელებდა, ეკლესია შეაჩვენებდა, საერო კანონით კი სიკვდილით დასჯიდნენ.\n• იმავე კრებაზე აღდგა ქუთაისის ეპარქია, ეკლესიას ჩამორთმეული მიწები დაუბრუნდა, გლეხები საეკლესიო გადასახადებისგან გათავისუფლდნენ.\n• ციხესიმაგრეები მეფის მმართველობაში გადავიდა — ზოგი მეფემ თავადებისგან იყიდა, ზოგი ურჩებს ჩამოართვა, ზოგიც ნებით გადასცეს.\n• ოსმალეთის გარნიზონები ტყვეთა სყიდვით დიდ შემოსავალს იღებდნენ. ამიტომ 1760-იან წლებში ოსმალებმა რამდენჯერმე ილაშქრეს იმერეთში და ლეკთა დაქირავებული ჯარიც შემოუსიეს. იმერეთი დასუსტდა, მაგრამ დაპყრობა ვერ შეძლეს.",
