                "• 1800 წელს პავლე I-მა „სათხოვარი პუნქტების“ ყველა პირობაზე ქართველ ელჩებს თანხმობა მისცა, მაგრამ ამავე დროს სამეფოს გაუქმებას გეგმავდა. გენერალ კნორინგს საიდუმლოდ სწერდა: მეფე ავადაა და როგორც კი გარდაიცვლება, ჩვენს ნებართვამდე მემკვიდრეს მეფედ ნუ აკურთხებენო.\n• 1800 წლის 18 დეკემბერს პავლე I-მა ხელი მოაწერა მანიფესტს ქართლ-კახეთის რუსეთთან შეერთების შესახებ — ის გიორგი XII-ის სიკვდილამდე არ უნდა გამოეცხადებინათ.\n• 1800 წლის 28 დეკემბერს გიორგი XII გარდაიცვალა. მისმა ვაჟმა დავითმა თავი სამეფოს გამგებლად გამოაცხადა და იმედოვნებდა, რომ იმპერატორი მას მეფედ დაამტკიცებდა.\n• 1801 წლის 11 მარტს პავლე I შეთქმულებმა მოკლეს. ახალმა იმპერატორმა, ალექსანდრე I-მა, საკითხი სახელმწიფო საბჭოს გადასცა, რომელმაც ხმის უმრავლესობით შეერთება დაამტკიცა.\n• 1801 წლის 12 სექტემბერს ალექსანდრე I-მა ხელი მოაწერა ქართლ-კახეთის სამეფოს გაუქმების მანიფესტს. მანიფესტში ეწერა, რომ რუსეთი საქართველოს მტრებისგან დასაცავად იღებდა და არა იმპერიის გასაფართოებლად. მმართველად გენერალი კნორინგი დაინიშნა.",
