                "• რესპუბლიკის გამოცხადების მნიშვნელობის ხაზგასასმელად გაუქმდა ჩვეული წელთაღრიცხვა ქრისტეს შობიდან. „ახალი ხანის“ დასაწყისად 1792 წლის სექტემბერი — რესპუბლიკის გამოცხადება — გამოცხადდა, წელიწადი კი 1 იანვრით აღარ იწყებოდა.\n• თვეებს წელიწადის დროებისა და სოფლის სამუშაოების შესაბამისი სახელები ეწოდა: მაგალითად, ვანდემიერი — რთველი, ნივოზი — თოვლის თვე, ფლორეალი — ყვავილობის თვე, თერმიდორი — სიცხის თვე.\n• ყოველი თვე 30 დღისგან შედგებოდა და შვიდდღიანი კვირის ნაცვლად დეკადებად — ათ-ათ დღედ — იყოფოდა.\n• წლის ბოლოს დარჩენილი დღეები უქმე დღეებად და დღესასწაულებად გამოცხადდა: ღირსების, ნიჭის, შრომისა და დაჯილდოების დღეები, ბოლოს კი — რევოლუციის დღე. ქრისტიანული დღესასწაულები კალენდრიდან ამოიღეს.",
